def transform(grid):
    H,W=len(grid),len(grid[0])
    rows=[i for i in range(H) if any(v for v in grid[i])]
    if not rows: return grid
    bot=max(rows); out=[[0]*W for _ in range(H)]
    for i in range(H):
        for j,v in enumerate(grid[i]):
            if v:
                nj=j+(i-bot)
                if 0<=nj<W: out[i][nj]=v
    return out

